-- boxers_search_idx, from packages/data-ops/src/schema.ts. drizzle-kit 0.31 splits SQLite index
-- expressions on commas when it writes them, so the two search keys (SEARCH_TEXT_KEY and
-- SEARCH_NAME_KEY in packages/data-ops/src/search.ts) are written out here as the schema declares
-- them; meta/0002_snapshot.json holds the same expressions. search.test.ts checks that this index
-- serves searchBoxers as a covering index.
CREATE INDEX `boxers_search_idx` ON `boxers` (lower(trim(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(name || ' ' || coalesce(nicknames, '') || ' ' || coalesce(nationality, '') || ' ' || coalesce(pro_division, ''), '''', ''), '"', ''), '`', ''), '?', ''), char(8216), ''), char(8217), ''), char(8220), ''), char(8221), ''), ',', ' '), '-', ' '), '.', ' '), '/', ' '), '\', ' '), '(', ' '), ')', ' '), ':', ' '), ';', ' '), '|', ' '), '&', ' '), '+', ' '), '  ', ' '), '  ', ' '), '  ', ' '))),lower(trim(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(name, '''', ''), '"', ''), '`', ''), '?', ''), char(8216), ''), char(8217), ''), char(8220), ''), char(8221), ''), ',', ' '), '-', ' '), '.', ' '), '/', ' '), '\', ' '), '(', ' '), ')', ' '), ':', ' '), ';', ' '), '|', ' '), '&', ' '), '+', ' '), '  ', ' '), '  ', ' '), '  ', ' '))),`pro_wins`,`pro_total_bouts`,`name`);